#include <iostream>
#include <string>
#include <iomanip>

// Base class: CommissionEmployee
class CommissionEmployee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn, double sales, double rate)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)),
          grossSales(sales), commissionRate(rate) {}

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }
    double getGrossSales() const { return grossSales; }
    double getCommissionRate() const { return commissionRate; }

    // Non-virtual print function
    void print() const {
        std::cout << "commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales;
    double commissionRate;
};

// Derived class: BasePlusCommissionEmployee
class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), std::move(ssn), sales, rate),
          baseSalary(salary) {}

    double getBaseSalary() const { return baseSalary; }
    void setBaseSalary(double salary) { baseSalary = salary; }

    // Redefined non-virtual print function
    void print() const {
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << baseSalary;
    }

private:
    double baseSalary;
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    CommissionEmployee baseEmployee("Sue", "Jones", "222-22-2222", 10000.0, 0.06);
    BasePlusCommissionEmployee derivedEmployee("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    // 1. Aim base pointer at derived object
    CommissionEmployee* basePtr = &derivedEmployee;

    std::cout << "Calling print via base-class pointer aimed at derived-class object:\n";
    basePtr->print(); // Calls CommissionEmployee::print due to static binding
    std::cout << "\n\nNotice: Base salary is NOT displayed because print() is non-virtual.\n";

    // 2. Base pointer can only invoke base-class interface
    std::cout << "Employee name via base pointer: " << basePtr->getFirstName() << " " << basePtr->getLastName() << "\n";

    return 0;
}

